#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
#
# Compare libabigail reports of a release branch against its ABI base with
# the branch's baseline of already accepted differences.
#
#   abi-baseline.py check <reports-dir> <baseline-file|->
#   abi-baseline.py write <reports-dir> <baseline-file>
#
# <reports-dir> holds one abidiff report per binary, named
# <binary-path-with-_>.txt (as written by abi/abigail-compare.sh with
# ABI_REPORT). Each interface difference becomes one line
# "<binary> | <entry header> | <detail; detail; ...>". Types that only left
# a binary's debug info and pure additions are not differences.
#
# check: exit 1 on any entry that is not in the baseline (a new break, or a
# further change to an accepted one) and on any baseline entry that no
# longer occurs (stale: remove it). A baseline of "-" is empty (major 26+).

import os
import re
import sys

SECTION = re.compile(r'^(\d+) (Removed|Changed|Added) (function|variable)s?:')
UNREACHABLE = re.compile(r'^(\d+) (removed|changed|added) types? unreachable')
# A changed type counts only when its own entry shows a layout change;
# entries that just repeat a change through a pointer or typedef do not.
LAYOUT = re.compile(r'type size changed|data member insertion|'
                    r'data member deletion|offset changed|type name changed|'
                    r'enumerator|was removed')


def entries(report, binary):
    """Yield normalised interface differences of one abidiff report."""
    with open(report) as f:
        lines = [l.rstrip('\n') for l in f]

    section = None          # e.g. ('Removed', 'function') or ('changed', 'types')
    header = None
    details = []

    def flush():
        if header is None:
            return None
        # abidiff pairs anonymous types between the two builds by position,
        # so reordered protocol headers pair unrelated structs; a real change
        # to an anonymous type is reported under its typedef or variable name
        if re.match(r"^(\[C\] )?'(const )?(struct|union|enum) \{", header):
            return None
        removed_symbol = section in (('Removed', 'function'),
                                     ('Removed', 'variable'))
        if not removed_symbol and not any(LAYOUT.search(d) for d in details):
            return None
        return '%s | %s | %s' % (binary, header, '; '.join(details))

    for line in lines:
        if not line.strip():
            e = flush()
            if e:
                yield e
            header, details = None, []
            continue
        m = SECTION.match(line)
        u = UNREACHABLE.match(line)
        if m or u:
            e = flush()
            if e:
                yield e
            header, details = None, []
            section = (m.group(2), m.group(3)) if m else (u.group(2), 'types')
            continue
        if line.endswith('summary:') or ' summary: ' in line:
            continue
        stripped = line.strip()
        # an entry header: a tagged line in a section, or a column-0
        # "'type' changed:" leaf entry
        tagged = re.match(r"^\s{2}\[[DCA]\] '", line)
        leaf = re.match(r"^'.*' changed:$", line)
        if tagged or leaf:
            e = flush()
            if e:
                yield e
            details = []
            if leaf:
                section = ('leaf', 'types')
            kind = section[0] if section else ''
            # additions and types that only left the debug info are no ABI
            # differences
            if kind in ('Added', 'added') or section == ('removed', 'types'):
                header = None
                continue
            header = re.sub(r'\s+\{[^}]*\}$', '', stripped)
            continue
        if header is not None:
            details.append(stripped)
    e = flush()
    if e:
        yield e


def collect(reports_dir):
    found = set()
    for name in sorted(os.listdir(reports_dir)):
        if not name.endswith('.txt'):
            continue
        binary = name[:-len('.txt')]
        found.update(entries(os.path.join(reports_dir, name), binary))
    return found


def read_baseline(path):
    if path == '-':
        return set()
    with open(path) as f:
        return {l.rstrip('\n') for l in f
                if l.strip() and not l.startswith('#')}


def main():
    if len(sys.argv) != 4 or sys.argv[1] not in ('check', 'write'):
        print(__doc__.strip().split('\n\n')[1], file=sys.stderr)
        return 2
    mode, reports_dir, baseline = sys.argv[1:]
    found = collect(reports_dir)
    if mode == 'write':
        with open(baseline, 'w') as f:
            f.write('# ABI differences accepted against the base release;\n'
                    '# one per line, generated by abi-baseline.py write.\n')
            for e in sorted(found):
                f.write(e + '\n')
        print('abi-baseline: wrote %d entries to %s' % (len(found), baseline))
        return 0
    accepted = read_baseline(baseline)
    new = sorted(found - accepted)
    stale = sorted(accepted - found)
    for e in new:
        print('abi-baseline: NEW: ' + e)
    for e in stale:
        print('abi-baseline: STALE (fixed, remove from the baseline): ' + e)
    print('abi-baseline: %d differences, %d accepted, %d new, %d stale' %
          (len(found), len(found & accepted), len(new), len(stale)))
    return 1 if new or stale else 0


if __name__ == '__main__':
    sys.exit(main())
